extends SceneTree
func _init() -> void:
	for n in [16, 56, 64]:
		var keys: PackedInt64Array = PackedInt64Array()
		keys.resize(n)
		var seed_v: int = 12345
		var reps: int = 2000
		var t0: int = Time.get_ticks_usec()
		for r in reps:
			for i in n:
				seed_v = (seed_v * 1103515245 + 12345) & 0x7FFFFFFF
				keys[i] = ((seed_v % 4096) << 8) | i
			for i in range(1, n):
				var v: int = keys[i]
				var pos: int = i
				for j in range(i - 1, -1, -1):
					if keys[j] <= v:
						break
					keys[j + 1] = keys[j]
					pos = j
				keys[pos] = v
		var dt: float = float(Time.get_ticks_usec() - t0) / float(reps)
		# verify sorted
		var ok: bool = true
		for i in range(1, n):
			if keys[i - 1] > keys[i]:
				ok = false
		print("for+break insertion sort n=", n, " us=", dt, " sorted=", ok)
	# worst case reverse-sorted 64
	var keys2: PackedInt64Array = PackedInt64Array()
	keys2.resize(64)
	var t1: int = Time.get_ticks_usec()
	for r in 2000:
		for i in 64:
			keys2[i] = ((64 - i) << 8) | i
		for i in range(1, 64):
			var v: int = keys2[i]
			var pos: int = i
			for j in range(i - 1, -1, -1):
				if keys2[j] <= v:
					break
				keys2[j + 1] = keys2[j]
				pos = j
			keys2[pos] = v
	print("reverse-sorted n=64 us=", float(Time.get_ticks_usec() - t1) / 2000.0)
	quit()
EOF
