extends SceneTree
class Holder:
	extends RefCounted
	var col: PackedInt64Array = PackedInt64Array()
	func at(i: int) -> int:
		return col[i]
func _init() -> void:
	var h: Holder = Holder.new()
	h.col.resize(4096)
	var reps: int = 200
	var t0: int = Time.get_ticks_usec()
	for r in reps:
		for i in 4096:
			h.col[i] = h.col[i] + 1
	print("member direct us/4096=", float(Time.get_ticks_usec() - t0) / float(reps))
	var loc: PackedInt64Array = h.col
	var t1: int = Time.get_ticks_usec()
	for r in reps:
		for i in 4096:
			loc[i] = loc[i] + 1
	print("local alias us/4096=", float(Time.get_ticks_usec() - t1) / float(reps))
	var t2: int = Time.get_ticks_usec()
	var acc: int = 0
	for r in reps:
		for i in 4096:
			acc += h.at(i)
	print("method accessor us/4096=", float(Time.get_ticks_usec() - t2) / float(reps))
	var t3: int = Time.get_ticks_usec()
	for r in reps:
		for i in 4096:
			acc += IntMath_floor_div(i + 7, 3)
	print("static call floor_div-like us/4096=", float(Time.get_ticks_usec() - t3) / float(reps))
	quit()
static func IntMath_floor_div(a: int, b: int) -> int:
	if b <= 0:
		return 0
	@warning_ignore("integer_division")
	return (a - posmod(a, b)) / b
EOF
